def _safe_resolve(root: str, fname: str) -> str:
    norm_root = os.path.abspath(root)
    parts = norm_root.split(os.sep)
    for i in range(len(parts)):
        p = os.sep.join(parts[:i+1]) if i > 0 else parts[0]
        if not p: continue
        try:
            if os.path.islink(p): raise CaptureError(f"Symlink in root: {p}")
            st = os.lstat(p)
            if getattr(st, 'st_file_attributes', 0) & 0x400:
                raise CaptureError(f"Reparse point in root: {p}")
        except OSError: pass
    root_r = os.path.realpath(root)
